package ai.platon.pulsar.ql

import org.junit.jupiter.api.DisplayName
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * Comprehensive integration tests for String UDFs.
 *
 * Tests the UDFs defined in:
 *   - [ai.platon.pulsar.ql.h2.udfs.StringFunctions] (namespace = "STR")
 *
 * The UDF aliases are generated by the H2 registration process:
 * "STR" + "_" + methodName, underscores stripped, uppercased.
 * H2 resolves function names case-insensitively and ignores underscores.
 */
class TestStringUdfs : QlIntegrationTestBase() {

    // -- isEmpty / isNotEmpty / isBlank / isNotBlank -------------------------

    @Test
    @DisplayName("test STR_IS_EMPTY returns true for empty string")
    fun testStrIsEmptyReturnsTrueForEmptyString() {
        query("SELECT STR_IS_EMPTY('') AS result") { rs ->
            assertTrue(rs.next())
            assertTrue(rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_EMPTY returns false for non-empty string")
    fun testStrIsEmptyReturnsFalseForNonEmptyString() {
        query("SELECT STR_IS_EMPTY('hello') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(false, rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_NOT_EMPTY returns false for empty string")
    fun testStrIsNotEmptyReturnsFalseForEmptyString() {
        query("SELECT STR_IS_NOT_EMPTY('') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(false, rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_NOT_EMPTY returns true for non-empty string")
    fun testStrIsNotEmptyReturnsTrueForNonEmptyString() {
        query("SELECT STR_IS_NOT_EMPTY('hello') AS result") { rs ->
            assertTrue(rs.next())
            assertTrue(rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_BLANK returns true for blank string")
    fun testStrIsBlankReturnsTrueForBlankString() {
        query("SELECT STR_IS_BLANK('   ') AS result") { rs ->
            assertTrue(rs.next())
            assertTrue(rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_BLANK returns false for non-blank string")
    fun testStrIsBlankReturnsFalseForNonBlankString() {
        query("SELECT STR_IS_BLANK('hello') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(false, rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_NOT_BLANK returns true for non-blank string")
    fun testStrIsNotBlankReturnsTrueForNonBlankString() {
        query("SELECT STR_IS_NOT_BLANK('hello') AS result") { rs ->
            assertTrue(rs.next())
            assertTrue(rs.getBoolean("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_IS_NOT_BLANK returns false for blank string")
    fun testStrIsNotBlankReturnsFalseForBlankString() {
        query("SELECT STR_IS_NOT_BLANK('   ') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(false, rs.getBoolean("RESULT"))
        }
    }

    // Note: STR_IS_ANY_EMPTY, STR_IS_NONE_EMPTY, STR_IS_ANY_BLANK, STR_IS_NONE_BLANK
    // take Array<String> parameters. H2's SQL parser does not support ARRAY[...]
    // as a direct function argument (the comma inside is parsed as parameter separator).
    // These thin wrappers around Apache Commons StringUtils are verified by Commons tests.

    // -- trim / strip variants --------------------------------------------------

    @Test
    @DisplayName("test STR_TRIM removes leading and trailing whitespace")
    fun testStrTrimRemovesLeadingTrailingWhitespace() {
        query("SELECT STR_TRIM('  hello  ') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("hello", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_TRIM_TO_NULL returns null for blank string")
    fun testStrTrimToNullReturnsNullForBlankString() {
        query("SELECT STR_TRIM_TO_NULL('   ') AS result") { rs ->
            assertTrue(rs.next())
            val result = rs.getString("RESULT")
            assertTrue(result == null || result == "", "Expected null or empty, got: $result")
        }
    }

    @Test
    @DisplayName("test STR_TRIM_TO_EMPTY returns empty for blank string")
    fun testStrTrimToEmptyReturnsEmptyForBlankString() {
        query("SELECT STR_TRIM_TO_EMPTY('   ') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_STRIP removes whitespace")
    fun testStrStripRemovesWhitespace() {
        query("SELECT STR_STRIP('  hello  ') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("hello", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_STRIP with stripChars removes specified chars")
    fun testStrStripWithStripCharsRemovesSpecifiedChars() {
        query("SELECT STR_STRIP('__hello__', '_') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("hello", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_STRIP_TO_NULL returns null for blank after strip")
    fun testStrStripToNullReturnsNullForBlankAfterStrip() {
        query("SELECT STR_STRIP_TO_NULL('   ') AS result") { rs ->
            assertTrue(rs.next())
            val result = rs.getString("RESULT")
            assertTrue(result == null || result == "", "Expected null or empty, got: $result")
        }
    }

    @Test
    @DisplayName("test STR_STRIP_TO_EMPTY returns empty for blank after strip")
