        query("SELECT STR_STRIP_TO_EMPTY('   ') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_STRIP_START removes leading chars")
