        query("SELECT STR_DEFAULT_IF_BLANK('   ', 'default') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("default", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_DEFAULT_IF_EMPTY returns default for empty")
    fun testStrDefaultIfEmptyReturnsDefaultForEmpty() {
        query("SELECT STR_DEFAULT_IF_EMPTY('', 'default') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("default", rs.getString("RESULT"))
        }
    }

    // -- abbreviate -------------------------------------------------------------

    @Test
    @DisplayName("test STR_ABBREVIATE abbreviates long string")
    fun testStrAbbreviateAbbreviatesLongString() {
        query("SELECT STR_ABBREVIATE('hello world this is a test', 15) AS result") { rs ->
            assertTrue(rs.next())
            val result = rs.getString("RESULT")
            assertTrue(result!!.endsWith("..."), "Expected abbreviation ending with '...', got: $result")
            assertTrue(result.length <= 15, "Expected length <= 15, got: ${result.length}")
        }
    }

    @Test
    @DisplayName("test STR_ABBREVIATE_MIDDLE abbreviates from middle")
    fun testStrAbbreviateMiddleAbbreviatesFromMiddle() {
        query("SELECT STR_ABBREVIATE_MIDDLE('hello world this is a test', '...', 20) AS result") { rs ->
            assertTrue(rs.next())
            val result = rs.getString("RESULT")
            assertTrue(result!!.length <= 20, "Expected length <= 20, got: ${result.length}")
        }
    }

    // -- difference / indexOfDifference / getCommonPrefix -----------------------

    @Test
    @DisplayName("test STR_DIFFERENCE returns the differing suffix")
    fun testStrDifferenceReturnsTheDifferingSuffix() {
        query("SELECT STR_DIFFERENCE('hello world', 'hello there') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("there", rs.getString("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_INDEX_OF_DIFFERENCE finds first differing index")
    fun testStrIndexOfDifferenceFindsFirstDifferingIndex() {
        query("SELECT STR_INDEX_OF_DIFFERENCE('hello', 'hexlo') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(2, rs.getInt("RESULT"))
        }
    }

    // Note: STR_GET_COMMON_PREFIX takes Array<String> parameter.
    // H2 SQL parser limitation prevents ARRAY[...] in function arguments.

    // -- normalizeSpace ---------------------------------------------------------

    @Test
    @DisplayName("test STR_NORMALIZE_SPACE collapses whitespace")
    fun testStrNormalizeSpaceCollapsesWhitespace() {
        query("SELECT STR_NORMALIZE_SPACE('hello   world  !') AS result") { rs ->
            assertTrue(rs.next())
            assertEquals("hello world !", rs.getString("RESULT"))
        }
    }

    // -- firstInteger / firstFloat (custom functions) ---------------------------

    @Test
    @DisplayName("test STR_FIRST_INTEGER extracts first integer from string")
    fun testStrFirstIntegerExtractsFirstIntegerFromString() {
        query("SELECT STR_FIRST_INTEGER('price is 199 dollars', 0) AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(199, rs.getInt("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_FIRST_FLOAT extracts first float from string")
    fun testStrFirstFloatExtractsFirstFloatFromString() {
        query("SELECT STR_FIRST_FLOAT('price is 19.99 dollars', 0.0) AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(19.99f, rs.getFloat("RESULT"))
        }
    }

    @Test
    @DisplayName("test STR_GET_FIRST_FLOAT_NUMBER extracts first float")
    fun testStrGetFirstFloatNumberExtractsFirstFloat() {
        query("SELECT STR_GET_FIRST_FLOAT_NUMBER('weight: 5.5 kg', 0.0) AS result") { rs ->
            assertTrue(rs.next())
            assertEquals(5.5f, rs.getFloat("RESULT"))
        }
    }
}
